        float gx[8];
        float gy[8];
        float gn;
        float tanAt(int k) {
            if (k <= 0 || float(k) >= gn - 1.0) return 0.0;
            float x0 = 0.0, y0 = 0.0, x1 = 0.0, y1 = 0.0, x2 = 0.0, y2 = 0.0;
            for (int j = 0; j < 8; j++) {
                if (j == k - 1) { x0 = gx[j]; y0 = gy[j]; }
                if (j == k) { x1 = gx[j]; y1 = gy[j]; }
                if (j == k + 1) { x2 = gx[j]; y2 = gy[j]; }
            }
            float d0 = (y1 - y0) / max(x1 - x0, 0.0001);
            float d1 = (y2 - y1) / max(x2 - x1, 0.0001);
            if (d0 * d1 <= 0.0) return 0.0;
            return 0.5 * (d0 + d1);
        }
        float curve(float x) {
            if (gn < 0.5) return 0.0;
            float xf = gx[0], yf = gy[0], xl = xf, yl = yf;
            for (int j = 1; j < 8; j++) {
                if (float(j) < gn) { xl = gx[j]; yl = gy[j]; }
            }
            if (x <= xf) return yf;
            if (x >= xl) return yl;
            int seg = 0;
            for (int j = 1; j < 7; j++) {
                if (float(j) < gn - 1.0 && x >= gx[j]) seg = j;
            }
            float xa = 0.0, ya = 0.0, xb = 1.0, yb = 0.0;
            for (int j = 0; j < 8; j++) {
                if (j == seg) { xa = gx[j]; ya = gy[j]; }
                if (j == seg + 1) { xb = gx[j]; yb = gy[j]; }
            }
            float h = max(xb - xa, 0.0001);
            float t = clamp((x - xa) / h, 0.0, 1.0);
            float m0 = tanAt(seg), m1 = tanAt(seg + 1);
            float t2 = t * t, t3 = t2 * t;
            return (2.0 * t3 - 3.0 * t2 + 1.0) * ya + (t3 - 2.0 * t2 + t) * h * m0 + (-2.0 * t3 + 3.0 * t2) * yb + (t3 - t2) * h * m1;
        }
        void load_hh() {
            gn = floor(amzp_hhN + 0.5);
            gx[0] = amzp_hhX0 / 100.0; gy[0] = clamp(amzp_hhY0 / 100.0, -1.0, 1.0);
            gx[1] = amzp_hhX1 / 100.0; gy[1] = clamp(amzp_hhY1 / 100.0, -1.0, 1.0);
            gx[2] = amzp_hhX2 / 100.0; gy[2] = clamp(amzp_hhY2 / 100.0, -1.0, 1.0);
            gx[3] = amzp_hhX3 / 100.0; gy[3] = clamp(amzp_hhY3 / 100.0, -1.0, 1.0);
            gx[4] = amzp_hhX4 / 100.0; gy[4] = clamp(amzp_hhY4 / 100.0, -1.0, 1.0);
            gx[5] = amzp_hhX5 / 100.0; gy[5] = clamp(amzp_hhY5 / 100.0, -1.0, 1.0);
            gx[6] = amzp_hhX6 / 100.0; gy[6] = clamp(amzp_hhY6 / 100.0, -1.0, 1.0);
            gx[7] = amzp_hhX7 / 100.0; gy[7] = clamp(amzp_hhY7 / 100.0, -1.0, 1.0);
        }
        void load_hs() {
            gn = floor(amzp_hsN + 0.5);
            gx[0] = amzp_hsX0 / 100.0; gy[0] = clamp(amzp_hsY0 / 100.0, -1.0, 1.0);
            gx[1] = amzp_hsX1 / 100.0; gy[1] = clamp(amzp_hsY1 / 100.0, -1.0, 1.0);
            gx[2] = amzp_hsX2 / 100.0; gy[2] = clamp(amzp_hsY2 / 100.0, -1.0, 1.0);
            gx[3] = amzp_hsX3 / 100.0; gy[3] = clamp(amzp_hsY3 / 100.0, -1.0, 1.0);
            gx[4] = amzp_hsX4 / 100.0; gy[4] = clamp(amzp_hsY4 / 100.0, -1.0, 1.0);
            gx[5] = amzp_hsX5 / 100.0; gy[5] = clamp(amzp_hsY5 / 100.0, -1.0, 1.0);
            gx[6] = amzp_hsX6 / 100.0; gy[6] = clamp(amzp_hsY6 / 100.0, -1.0, 1.0);
            gx[7] = amzp_hsX7 / 100.0; gy[7] = clamp(amzp_hsY7 / 100.0, -1.0, 1.0);
        }
        void load_ss() {
