            gx[3] = amzp_ssX3 / 100.0; gy[3] = clamp(amzp_ssY3 / 100.0, -1.0, 1.0);
            gx[4] = amzp_ssX4 / 100.0; gy[4] = clamp(amzp_ssY4 / 100.0, -1.0, 1.0);
            gx[5] = amzp_ssX5 / 100.0; gy[5] = clamp(amzp_ssY5 / 100.0, -1.0, 1.0);
            gx[6] = amzp_ssX6 / 100.0; gy[6] = clamp(amzp_ssY6 / 100.0, -1.0, 1.0);
            gx[7] = amzp_ssX7 / 100.0; gy[7] = clamp(amzp_ssY7 / 100.0, -1.0, 1.0);
        }
        void load_ls() {
            gn = floor(amzp_lsN + 0.5);
            gx[0] = amzp_lsX0 / 100.0; gy[0] = clamp(amzp_lsY0 / 100.0, -1.0, 1.0);
            gx[1] = amzp_lsX1 / 100.0; gy[1] = clamp(amzp_lsY1 / 100.0, -1.0, 1.0);
            gx[2] = amzp_lsX2 / 100.0; gy[2] = clamp(amzp_lsY2 / 100.0, -1.0, 1.0);
            gx[3] = amzp_lsX3 / 100.0; gy[3] = clamp(amzp_lsY3 / 100.0, -1.0, 1.0);
            gx[4] = amzp_lsX4 / 100.0; gy[4] = clamp(amzp_lsY4 / 100.0, -1.0, 1.0);
            gx[5] = amzp_lsX5 / 100.0; gy[5] = clamp(amzp_lsY5 / 100.0, -1.0, 1.0);
            gx[6] = amzp_lsX6 / 100.0; gy[6] = clamp(amzp_lsY6 / 100.0, -1.0, 1.0);
            gx[7] = amzp_lsX7 / 100.0; gy[7] = clamp(amzp_lsY7 / 100.0, -1.0, 1.0);
        }
        float3 rgb2hsv(float3 c) {
            float4 K = float4(0.0, -1.0 / 3.0, 2.0 / 3.0, -1.0);
            float4 p = mix(float4(c.bg, K.wz), float4(c.gb, K.xy), step(c.b, c.g));
            float4 q = mix(float4(p.xyw, c.r), float4(c.r, p.yzx), step(p.x, c.r));
            float d = q.x - min(q.w, q.y);
            float e = 1.0e-10;
            return float3(abs(q.z + (q.w - q.y) / (6.0 * d + e)), d / (q.x + e), q.x);
        }
        float3 hsv2rgb(float3 c) {
            float4 K = float4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
            float3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
            return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
        }
        float lumY(float3 c) { return dot(c, float3(0.2126, 0.7152, 0.0722)); }
        float band(float h, float c0, float cPrev, float cNext) {
            float d = h - c0;
            d = d - floor(d + 0.5);
            if (d >= 0.0) return clamp(1.0 - d / max(cNext, 0.0001), 0.0, 1.0);
            return clamp(1.0 + d / max(cPrev, 0.0001), 0.0, 1.0);
        }
        void amzRender() {
            float4 src = amzTexture(0, amzScreenNorm());
            float a = src.a;
            if (a <= 0.0001) {
                amzOutput = float4(0.0);
                return;
            }
            float3 c = clamp(src.rgb / a, 0.0, 1.0);
            float any = abs(amzp_mhH0)+abs(amzp_mhH1)+abs(amzp_mhH2)+abs(amzp_mhH3)+abs(amzp_mhH4)+abs(amzp_mhH5)+abs(amzp_mhH6)+abs(amzp_mhH7)
                      + abs(amzp_mhS0)+abs(amzp_mhS1)+abs(amzp_mhS2)+abs(amzp_mhS3)+abs(amzp_mhS4)+abs(amzp_mhS5)+abs(amzp_mhS6)+abs(amzp_mhS7)
                      + abs(amzp_mhL0)+abs(amzp_mhL1)+abs(amzp_mhL2)+abs(amzp_mhL3)+abs(amzp_mhL4)+abs(amzp_mhL5)+abs(amzp_mhL6)+abs(amzp_mhL7)
                      + amzp_hhN + amzp_hsN + amzp_ssN + amzp_lsN;
            if (any < 0.001) {
                amzOutput = src;
                return;
            }
            float3 hsv = rgb2hsv(c);
            float h = hsv.x, s = hsv.y, v = hsv.z;
            float w0 = band(h, 0.0, 60.0 / 360.0, 30.0 / 360.0);
            float w1 = band(h, 30.0 / 360.0, 30.0 / 360.0, 30.0 / 360.0);
            float w2 = band(h, 60.0 / 360.0, 30.0 / 360.0, 60.0 / 360.0);
            float w3 = band(h, 120.0 / 360.0, 60.0 / 360.0, 60.0 / 360.0);
            float w4 = band(h, 180.0 / 360.0, 60.0 / 360.0, 60.0 / 360.0);
            float w5 = band(h, 240.0 / 360.0, 60.0 / 360.0, 30.0 / 360.0);
            float w6 = band(h, 270.0 / 360.0, 30.0 / 360.0, 30.0 / 360.0);
            float w7 = band(h, 300.0 / 360.0, 30.0 / 360.0, 60.0 / 360.0);
            float dH = (w0*amzp_mhH0 + w1*amzp_mhH1 + w2*amzp_mhH2 + w3*amzp_mhH3 + w4*amzp_mhH4 + w5*amzp_mhH5 + w6*amzp_mhH6 + w7*amzp_mhH7) / 100.0;
            float dS = (w0*amzp_mhS0 + w1*amzp_mhS1 + w2*amzp_mhS2 + w3*amzp_mhS3 + w4*amzp_mhS4 + w5*amzp_mhS5 + w6*amzp_mhS6 + w7*amzp_mhS7) / 100.0;
            float dL = (w0*amzp_mhL0 + w1*amzp_mhL1 + w2*amzp_mhL2 + w3*amzp_mhL3 + w4*amzp_mhL4 + w5*amzp_mhL5 + w6*amzp_mhL6 + w7*amzp_mhL7) / 100.0;
            float sw = smoothstep(0.0, 0.25, s);
            h = fract(h + dH * (30.0 / 360.0) * sw);
            s = clamp(s * (1.0 + dS * sw), 0.0, 1.0);
            float3 o = hsv2rgb(float3(h, s, v));
            if (dL > 0.0) o = o + (1.0 - o) * dL * 0.55 * sw;
            else o = o * (1.0 + dL * 0.65 * sw);
            if (amzp_hhN + amzp_hsN + amzp_ssN + amzp_lsN > 0.5) {
                float3 q = rgb2hsv(clamp(o, 0.0, 1.0));
                float hh = q.x, ss = q.y;
                float cw = smoothstep(0.0, 0.12, ss);
                float mul = 1.0;
                if (amzp_hhN > 0.5) { load_hh(); hh = fract(q.x + curve(q.x) * 0.5 * cw); }
                if (amzp_hsN > 0.5) { load_hs(); mul *= 1.0 + curve(q.x); }
                if (amzp_ssN > 0.5) { load_ss(); mul *= 1.0 + curve(q.y); }
                if (amzp_lsN > 0.5) { load_ls(); mul *= 1.0 + curve(lumY(o)); }
                ss = clamp(ss * max(mul, 0.0), 0.0, 1.0);
                o = hsv2rgb(float3(hh, ss, q.z));
            }
            o = clamp(o, 0.0, 1.0);
            amzOutput = float4(o * a, a);
        }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
